Now let me look at the `HandleCommissioningGet` function more carefully. The issue is:

```cpp
void Leader::HandleCommissioningGet(Coap::Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
{
    MeshCoP::Tlv tlv;
    uint16_t     offset = aMessage.GetOffset();
    uint8_t      tlvs[NetworkData::kMaxSize];  // 254 bytes
    uint8_t      length = 0;

    while (offset < aMessage.GetLength())
    {
        aMessage.Read(offset, sizeof(tlv), &tlv);

        if (tlv.GetType() == MeshCoP::Tlv::kGet)
        {
            length = tlv.GetLength();  // <-- attacker-controlled length!
            aMessage.Read(offset + sizeof(MeshCoP::Tlv), length, tlvs);  // <-- can overflow tlvs!
            break;
        }

        offset += sizeof(tlv) + tlv.GetLength();
    }

    SendCommissioningGetResponse(aMessage, aMessageInfo, tlvs, length);
}
```

The `tlv.GetLength()` is read from the attacker-controlled message and can be larger than `sizeof(tlvs)` (254 bytes), causing a stack buffer overflow when reading into `tlvs`.

